import { beforeEach, describe, expect, it } from "vitest";

import {
  getDbLookupCallArgs,
  getDbLookupCallCount,
  resetDbLookupInstrumentation,
} from "../src/dbLookup";
import { semanticSearch } from "../src/semanticSearch";

beforeEach(() => {
  resetDbLookupInstrumentation();
});

describe("semanticSearch — correctness", () => {
  it("returns fully hydrated records in the ranking service's order (all-cache-hit query)", async () => {
    const results = await semanticSearch("intro to programming");

    expect(results.map((r) => r.classId)).toEqual([
      "COMPSCI-61A-001",
      "COMPSCI-61A-002",
      "COMPSCI-10-001",
    ]);
    expect(results[0].title).toBe(
      "The Structure and Interpretation of Computer Programs"
    );
    expect(results[2].title).toBe("The Beauty and Joy of Computing");
  });

  it("hydrates a genuine cache miss correctly and keeps rank order", async () => {
    const results = await semanticSearch("probability theory");

    expect(results.map((r) => r.classId)).toEqual([
      "STAT-134-001",
      "COMPSCI-70-001",
    ]);
    // STAT-134-001 is not in catalogCache -- this title can only have come
    // from a (fallback) dbLookup.
    expect(results[0].title).toBe("Concepts of Probability");
    expect(results[0].instructor).toBe("A. Bandeira");
  });

  it("silently drops an id that exists in neither the cache nor the DB", async () => {
    const results = await semanticSearch("web development");

    // "COMPSCI-999-001" is a stale ranking-service entry that no longer
    // resolves anywhere. It must be dropped, not thrown, and not returned
    // as undefined/a hole.
    expect(results.map((r) => r.classId)).toEqual(["COMPSCI-169-001"]);
    expect(results.every((r) => r !== undefined && r !== null)).toBe(true);
  });

  it("returns an empty array when the ranking service finds nothing", async () => {
    const results = await semanticSearch("medieval basket weaving");
    expect(results).toEqual([]);
  });
});

describe("semanticSearch — avoids the redundant DB round-trip", () => {
  it("does not call dbLookup at all when every ranked id is already warm in the cache", async () => {
    await semanticSearch("intro to programming");
    expect(getDbLookupCallCount()).toBe(0);
  });

  it("calls dbLookup exactly once, with only the missing id(s), on a genuine cache miss", async () => {
    await semanticSearch("probability theory");

    expect(getDbLookupCallCount()).toBe(1);
    // Must be scoped to the miss(es) only -- NOT the full ranked list.
    // ("COMPSCI-70-001" is cache-warm and must not be re-fetched.)
    expect(getDbLookupCallArgs()).toEqual([["STAT-134-001"]]);
  });

  it("still calls dbLookup at most once even when the miss resolves to nothing", async () => {
    await semanticSearch("web development");

    // "COMPSCI-999-001" is a miss in both the cache and the DB. A correct
    // implementation still only pays for a single batched fallback lookup.
    expect(getDbLookupCallCount()).toBe(1);
    expect(getDbLookupCallArgs()).toEqual([["COMPSCI-999-001"]]);
  });

  it("never calls dbLookup when the ranking service returns no results", async () => {
    await semanticSearch("medieval basket weaving");
    expect(getDbLookupCallCount()).toBe(0);
  });
});
